using Movers.Services.Currencies;
using System.Security.Cryptography; using System.Text; using Movers.Domain.Pickups; using Movers.Services.Tenancy;
namespace Movers.Services.Pickups;
public sealed class PickupService(IPickupRepository r,IPickupWorkRepository w,ITenantContext tenant,TimeProvider clock,Movers.Services.Numbering.IRecordNumbers numbers,CurrencyService currencies,Movers.Services.Crew.ICrewRepository crewRepo,Movers.Services.Tenants.ICompanyScope? companies = null):IPickupService {
 public async Task<PickupStatusModel?> UpdateStatus(Guid id,SavePickupStatusCommand c,CancellationToken t){var x=await r.Status(id,true,t);if(x is null)return null;x.Update(c.Code,c.Name,c.DisplayOrder,c.Color,c.IsCompleted);await r.Save(t);return S(x);} public async Task<PickupStatusModel?> SetStatusActive(Guid id,bool active,CancellationToken t){var x=await r.Status(id,true,t);if(x is null)return null;x.SetActive(active);await r.Save(t);return S(x);}
 public async Task<VehicleModel?> UpdateVehicle(Guid id,SaveVehicleCommand c,CancellationToken t){var x=await r.Vehicle(id,true,t);if(x is null)return null;if(c.CapacityCbm<=0)throw new InvalidOperationException("Vehicle capacity must be greater than zero.");x.Update(c.RegistrationNumber,c.Name,c.Type,c.CapacityCbm,c.DriverName,c.DriverPhone);await r.Save(t);return V(x);} public async Task<VehicleModel?> SetVehicleActive(Guid id,bool active,CancellationToken t){var x=await r.Vehicle(id,true,t);if(x is null)return null;x.SetActive(active);await r.Save(t);return V(x);}
 public async Task<PickupModel?> Update(Guid id,SavePickupCommand c,CancellationToken t){var x=await r.Pickup(id,true,t);if(x is null)return null;if(await r.Status(c.StatusId,false,t) is null)throw new InvalidOperationException("Select a pickup status.");if(c.VehicleId.HasValue&&await r.Vehicle(c.VehicleId.Value,false,t) is null)throw new InvalidOperationException("Vehicle was not found.");if(c.SalesLeadId.HasValue&&await w.LeadAsync(c.SalesLeadId.Value,t) is null)throw new InvalidOperationException("Sales lead was not found.");x.Update(c.CustomerName,c.Phone,c.Email,c.Address,c.ScheduledAtUtc,c.StatusId,c.VehicleId,c.Notes);if(c.SalesLeadId.HasValue)x.LinkSalesLead(c.SalesLeadId);await r.Save(t);return await M(x,t);}
 public async Task<IReadOnlyList<PickupStatusModel>> Statuses(CancellationToken t){var values=await r.Statuses(t);if(values.Count==0){r.Add(new PickupStatus(tenant.TenantId,"PLANNED","Planned",10,"blue",false));r.Add(new PickupStatus(tenant.TenantId,"CONFIRMED","Customer Confirmed",20,"cyan",false));r.Add(new PickupStatus(tenant.TenantId,"PACKING","Packing",30,"orange",false));r.Add(new PickupStatus(tenant.TenantId,"PICKED_UP","Picked Up",40,"green",true));await r.Save(t);values=await r.Statuses(t);}return values.Select(S).ToList();} public async Task<PickupStatusModel> CreateStatus(SavePickupStatusCommand c,CancellationToken t){var x=new PickupStatus(tenant.TenantId,c.Code,c.Name,c.DisplayOrder,c.Color,c.IsCompleted);r.Add(x);await r.Save(t);return S(x);} public async Task<IReadOnlyList<VehicleModel>> Vehicles(CancellationToken t)=>(await r.Vehicles(t)).Select(V).ToList(); public async Task<VehicleModel> CreateVehicle(SaveVehicleCommand c,CancellationToken t){if(c.CapacityCbm<=0)throw new InvalidOperationException("Vehicle capacity must be greater than zero.");var x=new Vehicle(tenant.TenantId,c.RegistrationNumber,c.Name,c.Type,c.CapacityCbm,c.DriverName,c.DriverPhone);r.Add(x);await r.Save(t);return V(x);}
 public async Task<IReadOnlyList<PickupModel>> List(CancellationToken t){var list=new List<PickupModel>();foreach(var x in await r.Pickups(t))list.Add(await M(x,t));return list;} public async Task<PickupModel> Create(SavePickupCommand c,CancellationToken t){c=c with {PickupNumber=await numbers.Next("PU",t)};if(await r.NumberExists(c.PickupNumber.Trim().ToUpperInvariant(),null,t))throw new InvalidOperationException("Pickup number already exists.");if(await r.Status(c.StatusId,false,t) is null)throw new InvalidOperationException("Select a pickup status.");if(c.VehicleId.HasValue&&await r.Vehicle(c.VehicleId.Value,false,t) is null)throw new InvalidOperationException("Vehicle was not found.");if(c.QuotationId.HasValue&&await r.Quotation(c.QuotationId.Value,t) is null)throw new InvalidOperationException("Quotation was not found.");if(c.SalesLeadId.HasValue&&await w.LeadAsync(c.SalesLeadId.Value,t) is null)throw new InvalidOperationException("Sales lead was not found.");var x=new Pickup(tenant.TenantId,c.PickupNumber,c.QuotationId,c.CustomerName,c.Phone,c.Email,c.Address,c.ScheduledAtUtc,c.StatusId,c.VehicleId,c.Notes);if(c.SalesLeadId.HasValue)x.LinkSalesLead(c.SalesLeadId);r.Add(x);await r.Save(t);return await M(x,t);}
 public async Task<PickupDetailModel?> Get(Guid id,CancellationToken t){var x=await r.Pickup(id,false,t);return x is null?null:await D(x,t);} public async Task<PickupDetailModel?> SaveDetails(Guid id,SavePickupDetailCommand c,CancellationToken t){var x=await r.Pickup(id,true,t);if(x is null)return null;if(x.PackagesLocked)throw new InvalidOperationException("Packing is shared or confirmed. Revoke an unanswered link before editing; confirmed packages are immutable.");x.Touch();var assignments=new List<PickupAssignment>();foreach(var a in c.Assignments){if(await r.Employee(a.EmployeeId,t) is null)throw new InvalidOperationException("Assigned employee was not found.");var tm=await CurrentTeam(a.EmployeeId,t);assignments.Add(new(tenant.TenantId,id,a.EmployeeId,a.Role,tm.Id,tm.Name,clock.GetUtcNow()));}var clashes=Movers.Services.Crew.ScheduleConflicts.Find(c.Assignments.Select(a=>a.EmployeeId).Distinct().ToList(),x.ScheduledAtUtc,x.ScheduledAtUtc.AddMinutes(x.DurationMinutes),"PICKUP",x.Id,await crewRepo.BookingsAsync(t),(await crewRepo.EmployeesAsync(t)).ToDictionary(e=>e.Id,e=>e.FirstName+" "+e.LastName));if(clashes.Count>0)throw new InvalidOperationException(Movers.Services.Crew.ScheduleConflicts.Describe(clashes));var existingTracking=(await r.Packages(id,t)).Select(p=>p.TrackingNumber).ToHashSet();var packages=new List<PickupPackage>();var packageItems=new List<PickupPackageItem>();for(var i=0;i<c.Packages.Count;i++){var p=c.Packages[i];if(await r.Box(p.BoxTypeId,t) is null)throw new InvalidOperationException("Select an active box type.");var tracking=p.TrackingNumber is not null && existingTracking.Remove(p.TrackingNumber) ? p.TrackingNumber : await numbers.Next("PKG",t);var entity=new PickupPackage(tenant.TenantId,id,p.BoxTypeId,tracking,p.Notes,p.RoomName,p.IsFragile);packages.Add(entity);foreach(var item in p.Items){if(item.Quantity<=0||string.IsNullOrWhiteSpace(item.ItemName))throw new InvalidOperationException("Package item and quantity are required.");packageItems.Add(new(tenant.TenantId,entity.Id,item.ItemName,item.Quantity,item.Notes,item.RoomName??p.RoomName,item.HouseholdItemId));}}var materials=new List<PickupMaterialUsage>();foreach(var m in c.Materials){var master=await r.Material(m.MaterialId,t)??throw new InvalidOperationException("Select an active packing material.");if(m.Quantity<=0)throw new InvalidOperationException("Material quantity must be greater than zero.");materials.Add(new(tenant.TenantId,id,m.MaterialId,m.Quantity,m.UnitCost??master.CurrentUnitCost));}foreach(var boxes in c.Packages.GroupBy(p=>p.BoxTypeId))foreach(var recipe in await w.RecipeAsync(boxes.Key,t)){var master=await r.Material(recipe.MaterialId,t);if(master is not null)materials.Add(new(tenant.TenantId,id,recipe.MaterialId,recipe.Quantity*boxes.Count(),master.CurrentUnitCost,true));}r.Replace(await r.Assignments(id,t),await r.Packages(id,t),await r.Materials(id,t),assignments,packages,packageItems,materials);await r.Save(t);return await D(x,t);}
 public async Task<PickupDetailModel?> AddTransaction(Guid id,AddTransactionCommand c,CancellationToken t){var x=await r.Pickup(id,false,t);if(x is null)return null;if(c.Amount<=0||!(c.Type.Equals("INCOME",StringComparison.OrdinalIgnoreCase)||c.Type.Equals("EXPENSE",StringComparison.OrdinalIgnoreCase)))throw new InvalidOperationException("Enter a valid income or expense.");var fx=await currencies.Resolve(c.Currency??(await currencies.Settings(t)).DefaultCurrency,DateOnly.FromDateTime(clock.GetUtcNow().UtcDateTime),c.ExchangeRate,t);CurrencyService.Amount(c.Amount,fx);var transaction=new PickupTransaction(tenant.TenantId,id,await numbers.Next("TXN",t),c.Type,c.Category,c.Amount,c.PaymentMethod,c.Notes);await currencies.SaveSnapshot(transaction.Id,fx,t);r.Add(transaction);await r.Save(t);return await D(x,t);}
 public async Task<PickupLinkModel> Link(Guid id,int days,CancellationToken t){if(days is<1 or>30)throw new InvalidOperationException("Link validity must be 1 to 30 days.");var x=await r.Pickup(id,true,t)??throw new InvalidOperationException("Pickup was not found.");var raw=Convert.ToHexString(RandomNumberGenerator.GetBytes(24)).ToLowerInvariant();var expires=clock.GetUtcNow().AddDays(days);x.Share(Hash(raw),expires);await r.Save(t);return new(raw,expires);} public async Task<PublicPickupModel?> Public(string token,CancellationToken t){var z=await r.Public(Hash(token),t);if(z is null||z.Value.Pickup.ConfirmationExpiresAtUtc<clock.GetUtcNow())return null;if(!tenant.IsResolved)tenant.SetTenant(z.Value.Tenant);if(companies is not null)await companies.UseCompanyOfAsync(z.Value.Pickup,t);return new(tenant.Company?.Name??z.Value.Tenant.Name,await M(z.Value.Pickup,t));} public async Task<PublicPickupModel?> Confirm(string token,ConfirmPickupCommand c,CancellationToken t){var z=await r.Public(Hash(token),t);if(z is null||z.Value.Pickup.ConfirmationExpiresAtUtc<clock.GetUtcNow())return null;if(!tenant.IsResolved)tenant.SetTenant(z.Value.Tenant);if(companies is not null)await companies.UseCompanyOfAsync(z.Value.Pickup,t);var x=await r.Pickup(z.Value.Pickup.Id,true,t);if(x is null)return null;x.Confirm(c.ScheduledAtUtc,c.Latitude,c.Longitude,c.Address);await r.Save(t);return new(tenant.Company?.Name??z.Value.Tenant.Name,await M(x,t));}
 private async Task<PickupModel> M(Pickup x,CancellationToken t){var s=await r.Status(x.StatusId,false,t);var v=x.VehicleId.HasValue?await r.Vehicle(x.VehicleId.Value,false,t):null;var q=x.QuotationId.HasValue?await r.Quotation(x.QuotationId.Value,t):null;var lead=x.SalesLeadId.HasValue?await w.LeadAsync(x.SalesLeadId.Value,t):null;return new(x.SerialNo,x.Id,x.PickupNumber,x.QuotationId,x.CustomerName,x.Phone,x.Email,x.Address,x.Latitude,x.Longitude,x.ScheduledAtUtc,x.ConfirmedAtUtc,x.StatusId,s?.Name??"Unknown",s?.Color,x.VehicleId,v?.RegistrationNumber,x.Notes,x.CreatedAtUtc,q?.QuotationNumber,x.SalesLeadId,lead?.LeadNumber,x.StartedAtUtc,x.EndedAtUtc,x.IsPaused,x.DistanceKm);} private async Task<PickupDetailModel> D(Pickup x,CancellationToken t){var a=new List<PickupAssignmentModel>();foreach(var y in await r.Assignments(x.Id,t)){var e=await r.Employee(y.EmployeeId,t);a.Add(new(y.EmployeeId,e?.FullName??"Unknown",y.Role));}var boxes=new List<PickupPackageModel>();var ps=await r.Packages(x.Id,t);var pi=await r.PackageItems(ps.Select(y=>y.Id).ToList(),t);foreach(var p in ps){var b=await r.Box(p.BoxTypeId,t);boxes.Add(new(p.SerialNo,p.Id,p.BoxTypeId,b?.Name??"Box",p.TrackingNumber,p.Notes,pi.Where(y=>y.PickupPackageId==p.Id).Select(y=>new PickupPackageItemModel(y.ItemName,y.Quantity,y.Notes,y.RoomName,y.HouseholdItemId)).ToList(),p.RoomName,p.IsFragile));}var mats=new List<PickupMaterialModel>();foreach(var m in await r.Materials(x.Id,t)){var master=await r.Material(m.MaterialId,t);mats.Add(new(m.MaterialId,master?.Name??"Material",master?.Unit??"",m.Quantity,m.UnitCost,m.TotalCost,m.IsBoxRecipe));}var tx=(await r.Transactions(x.Id,t)).Select(y=>new PickupTransactionModel(y.SerialNo,y.Id,y.TransactionNumber,y.Type,y.Category,y.Amount,y.PaymentMethod,y.Notes,y.CreatedAtUtc)).ToList();for(var i=0;i<tx.Count;i++){var fx=await currencies.Snapshot(tx[i].Id,t);tx[i]=tx[i] with{Currency=fx?.Currency,BaseAmount=fx is null?null:CurrencyService.ToBase(tx[i].Amount,fx)};}return new(await M(x,t),a,boxes,mats,tx,tx.Where(y=>y.Type=="INCOME").Sum(y=>y.Amount),tx.Where(y=>y.Type=="EXPENSE").Sum(y=>y.Amount));}
 private static PickupStatusModel S(PickupStatus x)=>new(x.SerialNo,x.Id,x.Code,x.Name,x.DisplayOrder,x.Color,x.IsCompleted,x.IsActive);private static VehicleModel V(Vehicle x)=>new(x.SerialNo,x.Id,x.RegistrationNumber,x.Name,x.Type,x.CapacityCbm,x.DriverName,x.DriverPhone,x.IsActive);private static string Hash(string x)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(x))).ToLowerInvariant();

 /// <summary>The team the employee belongs to right now, frozen onto the assignment. A later move must not
 /// change who was responsible for this pickup, so the name is copied in rather than joined at read time.</summary>
 private async Task<(Guid? Id,string? Name)> CurrentTeam(Guid employeeId,CancellationToken t){
  var open=await crewRepo.OpenMembershipsForEmployeeAsync(employeeId,t);
  var m=open.OrderByDescending(x=>x.JoinedAtUtc).FirstOrDefault();
  if(m is null)return (null,null);
  var team=await crewRepo.TeamAsync(m.TeamId,false,t);
  return (team?.Id,team?.Name);
 }
}
